@import "tailwindcss";

@theme {
  --font-sans: "IBM Plex Sans", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --color-bg: #0b0e13;
  --color-panel: #11161e;
  --color-line: #1f2733;
  --color-text: #e6edf3;
  --color-muted: #8b98a8;
  --color-accent: #4cc9f0;
  --color-kill: #ef4444;
  --color-inconclusive: #f59e0b;
  --color-promising: #22c55e;
  --color-cannot: #6b7280;
}

html, body, #root { height: 100%; }
body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

// Evidence panel: train and validation equity curves (lightweight-charts), the stats legend from the
// backtest_result event, and a baseline strip. Curves draw in over 600 ms when a result arrives.
import { ColorType, LineSeries, createChart, type IChartApi, type ISeriesApi } from "lightweight-charts";
import { useEffect, useRef } from "react";
import type { EquityPoint, Stats } from "../events";
import { int, pct } from "../fmt";
import type { UiState } from "../state";
import { toSeries } from "./equitySeries";

const COLORS = { panel: "#11161e", line: "#1f2733", muted: "#8b98a8", accent: "#4cc9f0" };
const DRAW_MS = 600;

function Curve({ points, color, reduced }: { points: EquityPoint[]; color: string; reduced: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<"Line"> | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const chart = createChart(el, {
      autoSize: true,
      layout: { background: { type: ColorType.Solid, color: COLORS.panel }, textColor: COLORS.muted, fontFamily: "JetBrains Mono", fontSize: 11, attributionLogo: false },
      grid: { vertLines: { color: COLORS.line }, horzLines: { color: COLORS.line } },
      rightPriceScale: { borderColor: COLORS.line },
      timeScale: { borderColor: COLORS.line, timeVisible: false },
      crosshair: { horzLine: { color: COLORS.muted }, vertLine: { color: COLORS.muted } },
      handleScroll: false,
      handleScale: false,
    });
    const series = chart.addSeries(LineSeries, {
      color, lineWidth: 2, priceLineVisible: false, lastValueVisible: true, crosshairMarkerVisible: false,
      priceFormat: { type: "custom", formatter: (v: number) => pct(v, 1), minMove: 0.001 },
    });
    chartRef.current = chart;
    seriesRef.current = series;
    return () => {
      chart.remove();
      chartRef.current = null;
      seriesRef.current = null;
    };
  }, [color]);

  useEffect(() => {
    const series = seriesRef.current, chart = chartRef.current;
    if (!series || !chart) return;
    const data = toSeries(points);
    if (data.length === 0 || reduced) {
      series.setData(data);
      chart.timeScale().fitContent();
      return;
    }
    let raf = 0;
    const start = performance.now();
    const step = (now: number) => {
      const p = Math.min(1, (now - start) / DRAW_MS);
      series.setData(data.slice(0, Math.max(1, Math.round(p * data.length))));
      chart.timeScale().fitContent();
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [points, reduced]);

  return <div ref={ref} className="h-full min-h-0 w-full" />;
}

function Legend({ label, stats, color }: { label: string; stats: Stats | null; color: string }) {
  return (
    <div className="flex flex-wrap items-baseline gap-x-3 gap-y-0.5 font-mono text-[11px]">
      <span className="font-semibold tracking-[0.14em]" style={{ color }}>{label}</span>
      {stats ? (
        <>
          <span className="text-muted">n <span className="text-text">{int(stats.n)}</span></span>
          <span className="text-muted">mean <span className="text-text">{pct(stats.mean)}</span></span>
          <span className="text-muted">95% <span className="text-text">[{pct(stats.ci_low)}, {pct(stats.ci_high)}]</span></span>
          <span className="text-muted">win <span className="text-text">{(stats.win_rate * 100).toFixed(0)}%</span></span>
        </>
      ) : (
        <span className="text-muted">waiting for backtest</span>
      )}
    </div>
  );
}

function BaselineStrip({ stats }: { stats: NonNullable<UiState["stats"]> }) {
  const rows = [
    { label: "v0 validation mean", value: stats.validation.mean, color: COLORS.accent },
    { label: "no-condition baseline", value: stats.baseline.mean, color: COLORS.muted },
  ];
  const max = Math.max(...rows.map((r) => Math.abs(r.value)), 1e-9);
  const paired = stats.baseline.paired_ci_low;
  return (
    <div className="grid grid-cols-[auto_1fr_auto] items-center gap-x-4 gap-y-1 border-t border-line pt-3 font-mono text-[11px]">
      {rows.map((r) => (
        <div key={r.label} className="contents">
          <span className="text-muted">{r.label}</span>
          <svg viewBox="0 0 200 10" preserveAspectRatio="none" className="h-2.5 w-full" aria-hidden>
            <line x1={100} y1={0} x2={100} y2={10} stroke={COLORS.line} />
            <rect x={r.value < 0 ? 100 - (Math.abs(r.value) / max) * 98 : 100} y={2} width={(Math.abs(r.value) / max) * 98} height={6} fill={r.color} />
          </svg>
          <span className="text-right text-text">{pct(r.value)}</span>
        </div>
      ))}
      <span className="col-span-3 pt-1 text-muted">
        paired lower bound (v0 minus baseline, 2.5th pct) <span style={{ color: paired > 0 ? "var(--color-promising)" : "var(--color-inconclusive)" }}>{pct(paired)}</span>
      </span>
    </div>
  );
}

export function EquityCurves({ state, reduced }: { state: UiState; reduced: boolean }) {
  const { stats } = state;
  return (
    <div className="grid h-full min-h-0 grid-rows-[auto_minmax(0,1fr)_auto] gap-3">
      <div className="grid grid-cols-2 gap-4">
        <Legend label="TRAIN" stats={stats?.train ?? null} color={COLORS.muted} />
        <Legend label="VALIDATION" stats={stats?.validation ?? null} color={COLORS.accent} />
      </div>
      <div className="grid min-h-0 grid-cols-2 gap-4">
        <Curve points={state.equityTrain} color={COLORS.muted} reduced={reduced} />
        <Curve points={state.equityValidation} color={COLORS.accent} reduced={reduced} />
      </div>
      {stats ? <BaselineStrip stats={stats} /> : <div className="border-t border-line pt-3 font-mono text-[11px] text-muted">cumulative return per trade, by entry date</div>}
    </div>
  );
}

// Objections panel (spec 16, item 5): the Naysayer's coded checks and its follow-ups, one card per event.
// Motion, all one-shot and tied to an event: a card lands (drops 10 px, settles from 102%, 320 ms, no bounce) and its
// border settles from the accent to its resting colour (600 ms) when its check_result or followup_requested arrives;
// a follow-up's result line and status badge appear when its backtest_result lands, and the badge changes once more
// when the verdict says whether the downgrade was applied. Reduced motion: opacity only, 150 ms.
import { motion } from "framer-motion";
import { useEffect, useRef } from "react";
import { appliedDowngrade, type Followup, type UiState } from "../state";

const EASE = [0.16, 1, 0.3, 1] as const;
// Hex copies of the index.css tokens: Framer can interpolate hex colours, not var() strings.
const HEX = { line: "#1f2733", accent: "#4cc9f0", amber: "#f59e0b" };

const CHECK_LABEL: Record<string, string> = {
  evidence: "Evidence", leakage: "Leakage", decay: "Out-of-sample decay", shared_window: "Shared window",
  cost_realism: "Cost realism", tail_risk: "Tail risk", data_drops: "Data drops",
};
// The follow-up menu names from spec section 4, shown until the result's own title arrives.
const FOLLOWUP_TITLE: Record<string, string> = { F1: "Earnings excluded", F2: "Per-year stability", F3: "Horizon sensitivity", F4: "Concentration" };

function landing(reduced: boolean, rest: string) {
  return reduced
    ? { initial: { opacity: 0, borderColor: rest }, animate: { opacity: 1, borderColor: rest }, transition: { duration: 0.15 } }
    : {
        initial: { opacity: 0, y: -10, scale: 1.02, borderColor: HEX.accent },
        animate: { opacity: 1, y: 0, scale: 1, borderColor: rest },
        transition: { duration: 0.32, ease: EASE, borderColor: { duration: 0.6, ease: EASE } },
      };
}

/** Keeps a card that just landed or changed visible when the panel scrolls (1280×800). Instant on purpose: the
 *  card's own landing is the motion, and smooth scrolls cancel each other when events arrive close together. */
function useInView<T extends HTMLElement>(dep: unknown) {
  const ref = useRef<T>(null);
  useEffect(() => {
    ref.current?.scrollIntoView?.({ block: "nearest" });
  }, [dep]);
  return ref;
}

function Heading({ children }: { children: string }) {
  return <h3 className="mb-2 font-mono text-[10px] uppercase tracking-[0.18em] text-muted">{children}</h3>;
}

function CheckCard({ c, reduced }: { c: UiState["checks"][number]; reduced: boolean }) {
  const ref = useInView<HTMLLIElement>(null);
  const label = CHECK_LABEL[c.check] ?? c.check.replace(/_/g, " ");
  return (
    <motion.li ref={ref} {...landing(reduced, c.passed ? HEX.line : HEX.amber)} className="rounded border bg-bg px-3 py-1" title={c.note}>
      <div className="flex min-w-0 items-baseline gap-2">
        <span className={`w-8 shrink-0 font-mono text-[10px] font-semibold tracking-[0.14em] ${c.passed ? "text-promising" : "text-inconclusive"}`}>
          {c.passed ? "PASS" : "FAIL"}
        </span>
        <span className="shrink-0 text-[13px] font-medium text-text">{label}</span>
        {/* Passed checks stay one quiet line; a failed check is an objection, so its note shows in full. */}
        {c.passed && <span className="min-w-0 truncate text-xs text-muted">{c.note}</span>}
      </div>
      {!c.passed && <p className="mt-0.5 pl-10 text-xs text-text/80">{c.note}</p>}
    </motion.li>
  );
}

function badge(f: Followup, verdict: UiState["verdict"]): { text: string; tone: "muted" | "amber" | "applied"; title?: string } {
  if (f.result === undefined && f.downgrade === undefined) return { text: "REQUESTED", tone: "muted" };
  if (f.skipped) return { text: "SKIPPED", tone: "muted" };
  if (!f.downgrade) return { text: "NO DOWNGRADE", tone: "muted" };
  // The rule text (cause) goes in the tooltip: the verdict stamp already lists every applied downgrade's cause.
  const rule = f.cause ? `rule: ${f.cause}` : "rule met";
  if (!verdict) return { text: "RULE MET", tone: "amber", title: rule };
  const applied = appliedDowngrade(f, verdict);
  if (applied) return { text: "RULE MET · APPLIED", tone: "applied", title: `${rule}\n${applied.from ?? "?"} → ${applied.to ?? "?"}` };
  return { text: "RULE MET · NOT APPLIED", tone: "muted", title: `${rule}\nfollow-ups only downgrade a promising verdict (verdict: ${verdict.verdict})` };
}

const TONE = {
  muted: "border-line text-muted",
  amber: "border-inconclusive/60 text-inconclusive",
  applied: "border-inconclusive bg-inconclusive text-bg",
};

function FollowupCard({ f, verdict, reduced }: { f: Followup; verdict: UiState["verdict"]; reduced: boolean }) {
  const b = badge(f, verdict);
  const ref = useInView<HTMLLIElement>(b.text);
  const enter = reduced ? { opacity: 0 } : { opacity: 0, y: 4 };
  return (
    <motion.li ref={ref} {...landing(reduced, f.downgrade ? HEX.amber : HEX.line)} className="rounded border bg-bg px-3 py-2">
      <div className="flex items-start justify-between gap-3">
        <div className="flex min-w-0 items-baseline gap-2">
          <span className="font-mono text-[11px] font-semibold text-accent">{f.id}</span>
          <span className="truncate text-[13px] font-medium text-text">{f.title ?? FOLLOWUP_TITLE[f.id] ?? "follow-up"}</span>
        </div>
        <motion.span
          key={b.text}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: reduced ? 0.15 : 0.2, ease: EASE }}
          title={b.title}
          className={`shrink-0 rounded-full border px-2 py-0.5 font-mono text-[10px] font-semibold tracking-[0.12em] ${TONE[b.tone]}`}
        >
          {b.text}
        </motion.span>
      </div>
      {f.reason && (
        <p className="mt-1 text-xs text-muted">
          <span className="font-mono text-[10px] uppercase tracking-[0.14em]">why </span>
          {f.reason}
        </p>
      )}
      {f.result !== undefined && (
        <motion.p initial={enter} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0.15 : 0.24, ease: EASE }} className="mt-1 font-mono text-[11px] leading-snug text-text">
          {f.result}
        </motion.p>
      )}
    </motion.li>
  );
}

export function Objections({ state, reduced }: { state: UiState; reduced: boolean }) {
  const { checks, followups, verdict } = state;
  if (checks.length === 0 && followups.length === 0) {
    return <p className="font-mono text-[11px] text-muted">{state.phase === "idle" ? "no audit loaded" : "waiting for the Naysayer"}</p>;
  }
  return (
    <div className="-mr-2 h-full overflow-y-auto pr-2">
      {checks.length > 0 && (
        <section>
          <Heading>Coded checks</Heading>
          <ul className="flex flex-col gap-1">
            {checks.map((c, i) => <CheckCard key={i} c={c} reduced={reduced} />)}
          </ul>
        </section>
      )}
      {followups.length > 0 && (
        <section className="mt-3">
          <Heading>Follow-ups</Heading>
          <ul className="flex flex-col gap-2">
            {followups.map((f) => <FollowupCard key={f.id} f={f} verdict={verdict} reduced={reduced} />)}
          </ul>
        </section>
      )}
    </div>
  );
}

